def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first position where chars differ
    min_len = min(len(s_in), len(s_out))

    # Check character by character
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found difference at position i
            # Determine what to replace and what to replace with
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we get here, one string is prefix of the other
    if len(s_in) > len(s_out):
        # Removal case
        old_char = s_in[min_len]
        new_char = ""
        return (old_char, new_char, min_len)
    else:
        # Insertion case  
        old_char = ""
        new_char = s_out[min_len]
        return (old_char, new_char, min_len)

